/**
 * Natural species rarity from POKEMON_POOL (post egg-pool rebuild).
 * Used by getNaturalRarity and save-load rarity reconciliation.
 */

import { RARITY, POKEMON_POOL, TYPES } from '../../constants/core.ts';
import { POKEMON_SPRITE_IDS } from '../../constants/balance/dexAndCapture.ts';
import { ENCOUNTER_SPRITE_IDS } from '../../constants/balance/encounterSpriteIds.ts';
import { resolveUltimateAbility } from './resolveUltimateAbility.ts';
import { resolveCanonicalSpeciesName } from './rosterSpeciesAliases.ts';
import type { CreatureData } from '../types/creature.js';
import type { PokedexEntry } from '../types/game/state.js';
import type { GameRuntime } from '../types/game.js';

const VALID_POKEMON_TYPES = new Set<string>(Object.values(TYPES));
const VALID_RARITIES = new Set<string>([RARITY.COMMON, RARITY.RARE, RARITY.EPIC, RARITY.LEGENDARY]);
const KNOWN_SPECIES = POKEMON_SPRITE_IDS as Record<string, number>;
const ENCOUNTER_SPECIES = ENCOUNTER_SPRITE_IDS as Record<string, number>;

const SPECIES_LOWER_TO_CANONICAL: Record<string, string> = {};
for (const speciesName of Object.keys(KNOWN_SPECIES)) {
    SPECIES_LOWER_TO_CANONICAL[speciesName.toLowerCase()] = speciesName;
}

const ENCOUNTER_SPECIES_LOWER: Record<string, string> = {};
for (const speciesName of Object.keys(ENCOUNTER_SPECIES)) {
    ENCOUNTER_SPECIES_LOWER[speciesName.toLowerCase()] = speciesName;
}

export const RARITY_TIER: Record<string, number> = {
    [RARITY.COMMON]: 1,
    [RARITY.RARE]: 2,
    [RARITY.EPIC]: 3,
    [RARITY.LEGENDARY]: 4,
};

export function rarityTier(rarity: string | undefined | null): number {
    return RARITY_TIER[String(rarity || RARITY.COMMON).toLowerCase()] ?? 0;
}

export function speciesNaturalRarity(speciesName: string): string {
    const canonicalName = findKnownSpeciesKey(speciesName) ?? resolveCanonicalSpeciesName(speciesName);
    const r = RARITY;
    const rarities = [r.LEGENDARY, r.EPIC, r.RARE, r.COMMON];
    const poolObj = POKEMON_POOL as Record<string, Record<string, string[]>>;

    for (const rarity of rarities) {
        const pool = poolObj[rarity];
        if (!pool) continue;
        for (const typeKey in pool) {
            const typePool = pool[typeKey];
            if (typePool?.includes(canonicalName)) return rarity;
        }
    }

    return r.COMMON;
}

function shouldUpgradeStoredRarity(storedRarity: string, naturalRarity: string): boolean {
    return rarityTier(naturalRarity) > rarityTier(storedRarity);
}

function isEpicOrLegendaryRarity(rarity: string | undefined | null): boolean {
    const r = String(rarity || '').toLowerCase();
    return r === RARITY.EPIC || r === RARITY.LEGENDARY;
}

function assignMissingPassiveTalent(creature: CreatureData): void {
    if (creature.passiveTalent) return;
    if (!isEpicOrLegendaryRarity(creature.rarity)) return;
    if (typeof creature.assignRandomTalent === 'function') {
        creature.assignRandomTalent();
    }
}

function refreshUltimateAbility(creature: CreatureData): void {
    if (!creature.name) return;
    creature.ultimateAbility = resolveUltimateAbility(creature.name, String(creature.rarity || RARITY.COMMON));
}

function collectStoredCreatures(game: GameRuntime): CreatureData[] {
    return [
        ...(game.playerTeam || []),
        ...(game.storage || []),
        ...(game.pension || []),
    ];
}

/** Upgrade stored creature rarity when the pool tier increased (idempotent). */
export function reconcileStoredCreatureRarity(game: GameRuntime): void {
    const creatures = collectStoredCreatures(game);

    for (const creature of creatures) {
        if (!creature?.name) continue;
        const natural = speciesNaturalRarity(creature.name);
        if (!shouldUpgradeStoredRarity(String(creature.rarity || RARITY.COMMON), natural)) continue;
        creature.rarity = natural;
        assignMissingPassiveTalent(creature);
        refreshUltimateAbility(creature);
        if (typeof creature.recalculateStats === 'function') {
            creature.recalculateStats();
        }
    }

    for (const creature of creatures) {
        if (!creature?.name) continue;
        assignMissingPassiveTalent(creature);
    }
}

export function parsePokedexKey(key: string): { name: string; type: string; rarity: string } | null {
    let normalized = String(key || '');
    if (!normalized) return null;
    if (normalized.endsWith('_shiny')) {
        normalized = normalized.slice(0, -'_shiny'.length);
    }
    const parts = normalized.split('_');
    if (parts.length < 3) return null;
    const rarity = parts[parts.length - 1];
    const type = parts[parts.length - 2];
    const name = parts.slice(0, -2).join('_');
    if (!name || !type || !rarity || rarity === 'shiny') return null;
    return { name, type, rarity };
}

export function canonicalPokedexKey(name: string, type: string, rarity: string): string {
    return `${name}_${type}_${rarity}`;
}

export function findKnownSpeciesKey(name: string): string | null {
    const raw = resolveCanonicalSpeciesName(String(name || '').trim());
    if (!raw) return null;
    if (Object.prototype.hasOwnProperty.call(KNOWN_SPECIES, raw)) return raw;
    if (Object.prototype.hasOwnProperty.call(ENCOUNTER_SPECIES, raw)) return raw;
    const lower = raw.toLowerCase();
    return SPECIES_LOWER_TO_CANONICAL[lower] ?? ENCOUNTER_SPECIES_LOWER[lower] ?? null;
}

export function isKnownSpecies(name: string): boolean {
    return findKnownSpeciesKey(name) != null;
}

export function getSpriteIdForSpecies(name: string): number | undefined {
    const key = findKnownSpeciesKey(name);
    if (!key) return undefined;
    const baseId = KNOWN_SPECIES[key];
    if (baseId !== undefined) return baseId;
    return ENCOUNTER_SPECIES[key];
}

function inferTypeFromPool(speciesName: string): string | null {
    const poolObj = POKEMON_POOL as Record<string, Record<string, string[]>>;
    const rarities = [RARITY.LEGENDARY, RARITY.EPIC, RARITY.RARE, RARITY.COMMON];
    for (const rarity of rarities) {
        const pool = poolObj[rarity];
        if (!pool) continue;
        for (const typeKey in pool) {
            if (pool[typeKey]?.includes(speciesName)) return typeKey;
        }
    }
    return null;
}

function extractTypeFromKeyFragment(key: string): string | null {
    const parts = String(key || '').split('_');
    for (const part of parts) {
        if (VALID_POKEMON_TYPES.has(part)) return part;
    }
    return null;
}

function tryRecoverSpeciesName(corruptedName: string): string | null {
    const raw = String(corruptedName || '');
    const idx = raw.lastIndexOf('_');
    if (idx <= 0) return null;
    const prefix = raw.slice(0, idx);
    const suffix = raw.slice(idx + 1);
    if (!VALID_POKEMON_TYPES.has(suffix)) return null;
    return findKnownSpeciesKey(prefix);
}

interface PokedexIdentity {
    name: string;
    type: string;
    rarity: string;
}

function resolvePokedexEntryIdentity(storageKey: string, entry: PokedexEntry): PokedexIdentity | null {
    const parsed = parsePokedexKey(storageKey);
    let name = parsed?.name ? findKnownSpeciesKey(parsed.name) : null;
    if (!name) {
        name = findKnownSpeciesKey(String(entry.name || ''));
    }
    if (!name) {
        name = tryRecoverSpeciesName(String(entry.name || ''));
    }
    if (!name || !isKnownSpecies(name)) return null;

    let type = parsed?.type || String(entry.type || '');
    let rarity = parsed?.rarity || String(entry.rarity || '');

    if (VALID_RARITIES.has(type) && !VALID_POKEMON_TYPES.has(type)) {
        if (!rarity || rarity === 'shiny' || !VALID_RARITIES.has(rarity)) {
            rarity = type;
        }
        type = '';
    }

    if (!type || !VALID_POKEMON_TYPES.has(type)) {
        type = extractTypeFromKeyFragment(storageKey) || inferTypeFromPool(name) || '';
    }
    if (!type || !VALID_POKEMON_TYPES.has(type)) return null;

    if (!rarity || rarity === 'shiny' || !VALID_RARITIES.has(rarity)) {
        rarity = speciesNaturalRarity(name);
    }

    return { name, type, rarity };
}

function mergeShinySuffixKeys(pokedex: Record<string, PokedexEntry>): void {
    const shinyKeys = Object.keys(pokedex).filter((key) => key.endsWith('_shiny'));
    for (const oldKey of shinyKeys) {
        const entry = pokedex[oldKey];
        if (!entry || typeof entry !== 'object') {
            delete pokedex[oldKey];
            continue;
        }

        const canonicalKey = oldKey.slice(0, -'_shiny'.length);
        const parsed = parsePokedexKey(canonicalKey);
        if (!parsed) {
            delete pokedex[oldKey];
            continue;
        }

        const { name, type, rarity } = parsed;
        entry.name = name;
        entry.type = type;
        entry.rarity = rarity;

        const existing = pokedex[canonicalKey];
        if (existing) {
            mergePokedexEntries(existing, entry);
            existing.name = name;
            existing.type = type;
            existing.rarity = rarity;
        } else {
            pokedex[canonicalKey] = { ...entry, name, type, rarity };
        }
        delete pokedex[oldKey];
    }
}

function rekeyPokedexEntries(pokedex: Record<string, PokedexEntry>): void {
    const keysToDelete: string[] = [];
    for (const oldKey of Object.keys(pokedex)) {
        const entry = pokedex[oldKey];
        if (!entry || typeof entry !== 'object') {
            keysToDelete.push(oldKey);
            continue;
        }

        const identity = resolvePokedexEntryIdentity(oldKey, entry);
        if (!identity) {
            keysToDelete.push(oldKey);
            continue;
        }

        const newKey = canonicalPokedexKey(identity.name, identity.type, identity.rarity);
        if (newKey === oldKey) {
            entry.name = identity.name;
            entry.type = identity.type;
            entry.rarity = identity.rarity;
            continue;
        }

        const normalized: PokedexEntry = { ...entry, ...identity };
        const existing = pokedex[newKey];
        if (existing) {
            mergePokedexEntries(existing, normalized);
            existing.name = identity.name;
            existing.type = identity.type;
            existing.rarity = identity.rarity;
        } else {
            pokedex[newKey] = normalized;
        }
        keysToDelete.push(oldKey);
    }

    for (const key of keysToDelete) {
        delete pokedex[key];
    }
}

function purgeInvalidPokedexEntries(pokedex: Record<string, PokedexEntry>): void {
    for (const key of Object.keys(pokedex)) {
        const entry = pokedex[key];
        if (!entry || typeof entry !== 'object') {
            delete pokedex[key];
            continue;
        }
        const rawName = String(entry.name || '').trim();
        if (!rawName || rawName.toLowerCase() === 'shiny') {
            delete pokedex[key];
            continue;
        }
        if (!isKnownSpecies(rawName)) {
            delete pokedex[key];
        }
    }
}

/** Merge legacy _shiny-suffixed keys, re-key orphans, and purge invalid entries. */
export function repairCorruptedPokedexKeys(
    pokedex: Record<string, PokedexEntry> | null | undefined,
): void {
    if (!pokedex || typeof pokedex !== 'object') return;

    mergeShinySuffixKeys(pokedex);
    rekeyPokedexEntries(pokedex);
    purgeInvalidPokedexEntries(pokedex);
}

function mergePokedexEntries(target: PokedexEntry, source: PokedexEntry): void {
    target.count = (Number(target.count) || 0) + (Number(source.count) || 0);
    target.shinyCount = (Number(target.shinyCount) || 0) + (Number(source.shinyCount) || 0);
    target.shadowCount = (Number(target.shadowCount) || 0) + (Number(source.shadowCount) || 0);
    target.seen = !!(target.seen || source.seen);
    target.caught = !!(target.caught || source.caught);
    target.shinySeen = !!(target.shinySeen || source.shinySeen);
    target.shinyCaught = !!(target.shinyCaught || source.shinyCaught);
    target.hasShiny = !!(target.hasShiny || source.hasShiny);
    target.hasShadow = !!(target.hasShadow || source.hasShadow);
    target.discovered = !!(target.discovered || source.discovered);

    const targetFirst = Number(target.firstDiscoveredAt);
    const sourceFirst = Number(source.firstDiscoveredAt);
    if (Number.isFinite(sourceFirst) && sourceFirst > 0) {
        if (!Number.isFinite(targetFirst) || targetFirst <= 0) {
            target.firstDiscoveredAt = sourceFirst;
        } else {
            target.firstDiscoveredAt = Math.min(targetFirst, sourceFirst);
        }
    }
}

/** Merge pokédex keys when stored rarity is below the current pool tier. */
export function migratePokedexRarityKeys(
    pokedex: Record<string, PokedexEntry> | null | undefined,
): void {
    if (!pokedex || typeof pokedex !== 'object') return;

    const keys = Object.keys(pokedex);
    for (const oldKey of keys) {
        const entry: PokedexEntry | undefined = pokedex[oldKey];
        if (!entry || typeof entry !== 'object') continue;

        const parsed = parsePokedexKey(oldKey);
        const name: string = parsed?.name || String(entry.name || '');
        const type: string = parsed?.type || String(entry.type || '');
        const oldRarity = parsed?.rarity || String(entry.rarity || RARITY.COMMON);
        if (!name || !type) continue;

        const newRarity = speciesNaturalRarity(name);
        if (!shouldUpgradeStoredRarity(oldRarity, newRarity)) {
            if (entry.rarity !== newRarity) entry.rarity = oldRarity;
            continue;
        }

        const newKey = `${name}_${type}_${newRarity}`;
        if (newKey === oldKey) {
            entry.rarity = newRarity;
            continue;
        }

        const existing = pokedex[newKey];
        if (existing) {
            mergePokedexEntries(existing, entry);
            existing.name = name;
            existing.type = type;
            existing.rarity = newRarity;
        } else {
            pokedex[newKey] = {
                ...entry,
                name,
                type,
                rarity: newRarity,
            };
        }
        delete pokedex[oldKey];
    }
}
