import { RARITY } from '../../constants/core.ts';
import {
    POKEMON_ULTIMATE_ABILITIES,
    GENERIC_ULTIMATES,
    ULTIMATE_CHARGE_NEEDED_MULTIPLIER,
    ENEMY_PVP_ULTIMATE_CHARGE_NEEDED_DIVISOR,
} from '../../constants/balance/talentsAndCombat.ts';
import type { UltimateAbility } from '../types/creature.js';

function applyUltimateChargeMultiplier(ability: UltimateAbility): UltimateAbility {
    if (ULTIMATE_CHARGE_NEEDED_MULTIPLIER === 1) return ability;

    const chargeNeeded = Math.round((ability.chargeNeeded ?? 100) * ULTIMATE_CHARGE_NEEDED_MULTIPLIER);
    const effect = ability.effect;
    const bonusCharge = effect?.bonusCharge;
    const scaledEffect =
        effect && bonusCharge != null
            ? { ...effect, bonusCharge: Math.round(bonusCharge * ULTIMATE_CHARGE_NEEDED_MULTIPLIER) }
            : effect;

    return { ...ability, chargeNeeded, effect: scaledEffect };
}

/** Scale ultimate charge for enemy PvP (after global multiplier). */
export function scaleUltimateChargeForEnemyPvp(ability: UltimateAbility): UltimateAbility {
    if (ENEMY_PVP_ULTIMATE_CHARGE_NEEDED_DIVISOR === 1) return ability;

    const chargeNeeded = Math.round((ability.chargeNeeded ?? 100) / ENEMY_PVP_ULTIMATE_CHARGE_NEEDED_DIVISOR);
    const effect = ability.effect;
    const bonusCharge = effect?.bonusCharge;
    const scaledEffect =
        effect && bonusCharge != null
            ? { ...effect, bonusCharge: Math.round(bonusCharge / ENEMY_PVP_ULTIMATE_CHARGE_NEEDED_DIVISOR) }
            : effect;

    return { ...ability, chargeNeeded, effect: scaledEffect };
}

/** Resolve personalized ultimate by species name, or generic fallback by rarity. */
export function resolveUltimateAbility(speciesName: string, rarity: string): UltimateAbility {
    const personalized = (POKEMON_ULTIMATE_ABILITIES as Record<string, UltimateAbility | undefined>)[speciesName];
    if (personalized) return applyUltimateChargeMultiplier(personalized);

    if (rarity === RARITY.LEGENDARY) return applyUltimateChargeMultiplier(GENERIC_ULTIMATES[RARITY.LEGENDARY]);
    if (rarity === RARITY.EPIC) return applyUltimateChargeMultiplier(GENERIC_ULTIMATES[RARITY.EPIC]);
    if (rarity === RARITY.RARE) return applyUltimateChargeMultiplier(GENERIC_ULTIMATES[RARITY.RARE]);
    return applyUltimateChargeMultiplier(GENERIC_ULTIMATES[RARITY.COMMON]);
}
